python3 - <<'PY'
p='src/ir_lower/expr/call_arg_coercion.rs'
s=open(p).read()
old = """    if !by_ref_array_arg_needs_mixed_storage(ctx, name, param_ty) {
        return None;
    }
    let array_ty = PhpType::Array(Box::new(PhpType::Mixed));
    let local = ctx.load_local(name, Some(arg.span));
    let converted = ctx.emit_value(
        Op::ArrayToMixed,
        vec![local.value],
        None,
        array_ty.clone(),
        Op::ArrayToMixed.default_effects(),
        Some(arg.span),
    );
    ctx.store_call_normalized_local(name, converted, array_ty, Some(arg.span));
    Some(ctx.load_local(name, Some(arg.span)).value)
}"""
new = """    let (op, array_ty) = by_ref_array_arg_mixed_storage_conversion(ctx, name, param_ty)?;
    let local = ctx.load_local(name, Some(arg.span));
    let converted = ctx.emit_value(
        op,
        vec![local.value],
        None,
        array_ty.clone(),
        op.default_effects(),
        Some(arg.span),
    );
    ctx.store_call_normalized_local(name, converted, array_ty, Some(arg.span));
    Some(ctx.load_local(name, Some(arg.span)).value)
}"""
assert s.count(old)==1
s=s.replace(old,new)

old2 = """pub(super) fn by_ref_array_arg_needs_mixed_storage(
    ctx: &LoweringContext<'_, '_>,
    name: &str,
    param_ty: &PhpType,
) -> bool {
    let PhpType::Array(param_elem) = param_ty.codegen_repr() else {
        return false;
    };
    if param_elem.codegen_repr() != PhpType::Mixed {
        return false;
    }
    let PhpType::Array(local_elem) = ctx.local_type(name).codegen_repr() else {
        return false;
    };
    local_elem.codegen_repr() != PhpType::Mixed
}"""
new2 = """pub(super) fn by_ref_array_arg_needs_mixed_storage(
    ctx: &LoweringContext<'_, '_>,
    name: &str,
    param_ty: &PhpType,
) -> bool {
    by_ref_array_arg_mixed_storage_conversion(ctx, name, param_ty).is_some()
}

/// Returns the op and result type that box a by-reference argument's element slots.
///
/// A HASH needs `Op::HashToMixed` where a list needs `Op::ArrayToMixed`, and leaving the hash
/// case out meant `f($assoc)` with `function f(array &$a)` handed a raw-slot hash to a body
/// compiled for boxed ones: `["x" => 1, "y" => 2]` came back as two ADDRESSES.
fn by_ref_array_arg_mixed_storage_conversion(
    ctx: &LoweringContext<'_, '_>,
    name: &str,
    param_ty: &PhpType,
) -> Option<(Op, PhpType)> {
    let local_ty = ctx.local_type(name).codegen_repr();
    match (param_ty.codegen_repr(), local_ty) {
        (PhpType::Array(param_elem), PhpType::Array(local_elem))
            if param_elem.codegen_repr() == PhpType::Mixed
                && local_elem.codegen_repr() != PhpType::Mixed =>
        {
            Some((
                Op::ArrayToMixed,
                PhpType::Array(Box::new(PhpType::Mixed)),
            ))
        }
        (
            PhpType::AssocArray {
                value: param_value, ..
            },
            PhpType::AssocArray {
                key: local_key,
                value: local_value,
            },
        ) if param_value.codegen_repr() == PhpType::Mixed
            && local_value.codegen_repr() != PhpType::Mixed =>
        {
            Some((
                Op::HashToMixed,
                PhpType::AssocArray {
                    key: local_key,
                    value: Box::new(PhpType::Mixed),
                },
            ))
        }
        _ => None,
    }
}"""
assert s.count(old2)==1
open(p,'w').write(s.replace(old2,new2))
print('assoc coercion added')
